UPDATE insurance_type
type_name = #{typeName}, category = #{category}, base_rate = #{baseRate}, min_amount = #{minAmount}, max_amount = #{maxAmount}, status = #{status}, description = #{description},
WHERE id = #{id}

mapper.select:
SELECT FROM insurance_type
AND (type_name LIKE CONCAT('%', #{keyword}, '%') OR type_code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY id ASC LIMIT #{limit}
